 import React, { useState, useEffect } from 'react'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import { Link } from 'react-router-dom'

export default function Notifications() {
    const { user } = useAuth()
    const [notifications, setNotifications] = useState([])
    const [loading, setLoading] = useState(true)
    const [unreadCount, setUnreadCount] = useState(0)

    useEffect(() => {
        loadNotifications()
    }, [user])

    const loadNotifications = async () => {
        setLoading(true)
        try {
            const { data, error } = await supabase
                .from('notifications')
                .select(`
                    *,
                    from_user:from_user_id (id, username, full_name, avatar_url)
                `)
                .eq('user_id', user?.id)
                .order('created_at', { ascending: false })
                .limit(50)

            if (error) throw error
            setNotifications(data || [])
            setUnreadCount(data?.filter(n => !n.read).length || 0)
        } catch (error) {
            console.error('Error loading notifications:', error)
        } finally {
            setLoading(false)
        }
    }

    const markAsRead = async (notificationId) => {
        try {
            await supabase
                .from('notifications')
                .update({ read: true })
                .eq('id', notificationId)
            
            setNotifications(prev => 
                prev.map(n => 
                    n.id === notificationId ? { ...n, read: true } : n
                )
            )
            setUnreadCount(prev => Math.max(0, prev - 1))
        } catch (error) {
            console.error('Error marking notification as read:', error)
        }
    }

    const markAllAsRead = async () => {
        try {
            await supabase
                .from('notifications')
                .update({ read: true })
                .eq('user_id', user?.id)
                .eq('read', false)
            
            setNotifications(prev => 
                prev.map(n => ({ ...n, read: true }))
            )
            setUnreadCount(0)
        } catch (error) {
            console.error('Error marking all as read:', error)
        }
    }

    const getNotificationIcon = (type) => {
        switch(type) {
            case 'like': return '❤️'
            case 'comment': return '💬'
            case 'follow': return '➕'
            case 'reply': return '↩️'
            case 'join': return '🏛️'
            case 'post': return '📝'
            default: return '🔔'
        }
    }

    const getNotificationLink = (notification) => {
        if (notification.type === 'follow') {
            return `/profile/${notification.from_user_id}`
        }
        if (notification.type === 'like' || notification.type === 'comment' || notification.type === 'reply') {
            return `/feed`
        }
        if (notification.type === 'join') {
            return `/community/${notification.community_id}`
        }
        return '#'
    }

    if (!user) {
        return (
            <div className="text-center py-12">
                <div className="text-gray-500">Please sign in to view notifications</div>
            </div>
        )
    }

    return (
        <div className="max-w-3xl mx-auto">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-2xl font-bold text-gray-800">🔔 Notifications</h1>
                    <p className="text-gray-500">Stay updated with what's happening</p>
                </div>
                {unreadCount > 0 && (
                    <button
                        onClick={markAllAsRead}
                        className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition text-sm"
                    >
                        Mark all as read ({unreadCount})
                    </button>
                )}
            </div>

            {loading ? (
                <div className="text-center py-12">
                    <div className="text-gray-500">Loading notifications...</div>
                </div>
            ) : notifications.length === 0 ? (
                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                    <div className="text-4xl mb-4">🔕</div>
                    <p className="text-gray-500">No notifications yet</p>
                    <p className="text-sm text-gray-400">When someone interacts with your posts, you'll see it here</p>
                </div>
            ) : (
                <div className="space-y-2">
                    {notifications.map((notification) => (
                        <Link
                            key={notification.id}
                            to={getNotificationLink(notification)}
                            onClick={() => markAsRead(notification.id)}
                            className={`block p-4 rounded-xl transition ${
                                notification.read
                                    ? 'bg-white hover:bg-gray-50'
                                    : 'bg-green-50 hover:bg-green-100 border-l-4 border-green-500'
                            }`}
                        >
                            <div className="flex items-start gap-4">
                                <div className="text-2xl">
                                    {getNotificationIcon(notification.type)}
                                </div>
                                <div className="flex-1">
                                    <div className="flex items-center gap-2">
                                        <span className="font-semibold text-gray-800">
                                            {notification.from_user?.full_name || notification.from_user?.username || 'Someone'}
                                        </span>
                                        <span className="text-gray-600">
                                            {notification.message}
                                        </span>
                                    </div>
                                    <div className="text-sm text-gray-400 mt-1">
                                        {new Date(notification.created_at).toLocaleDateString()} at {new Date(notification.created_at).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                    </div>
                                </div>
                                {!notification.read && (
                                    <span className="w-2 h-2 bg-green-500 rounded-full flex-shrink-0 mt-2"></span>
                                )}
                            </div>
                        </Link>
                    ))}
                </div>
            )}
        </div>
    )
}
